const originalNodes=new WeakMap();const originalAttrs=new WeakMap();const title=document.title;let currentLang="en";
const clean=value=>value.replace(/\s+/g," ").trim();
function localize(node){
 if(!node?.isConnected||node.parentElement?.closest("script,style,select,textarea,option,.page-language-picker,[contenteditable]"))return;
 const now=node.nodeValue;let record=originalNodes.get(node);
 if(!record||now!==record.last){record={raw:now,clean:clean(now),last:now};originalNodes.set(node,record)}
 const translated=dictionaries[currentLang]?.[record.clean];
 const wanted=translated===undefined?record.raw:record.raw.replace(record.clean,translated);
 if(now!==wanted){node.nodeValue=wanted;record.last=wanted}
}
function localizeAttrs(el){
 if(!el?.isConnected||el.closest("script,style,.page-language-picker"))return;
 let stored=originalAttrs.get(el);if(!stored){stored={};originalAttrs.set(el,stored)}
 for(const key of ["placeholder","aria-label","title"]){
  if(!el.hasAttribute(key))continue;
  const now=el.getAttribute(key);let record=stored[key];
  if(!record||record.last!==now)record=stored[key]={original:now,last:now};
  const wanted=dictionaries[currentLang]?.[record.original]??record.original;
  if(now!==wanted){el.setAttribute(key,wanted);record.last=wanted}
 }
}
function walkAndLocalize(root){
 if(root.nodeType===Node.TEXT_NODE){localize(root);return}
 if(root.nodeType!==Node.ELEMENT_NODE)return;
 if(root.closest(".page-language-picker,script,style"))return;
 localizeAttrs(root);
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode())localize(node);
 for(const el of root.querySelectorAll("[placeholder],[aria-label],[title]"))localizeAttrs(el);
}
let observer;
function translateNow(){
 observer?.disconnect();
 walkAndLocalize(document.body);
 document.documentElement.lang=currentLang;
 document.title=dictionaries[currentLang]?.[title]??title;
 observer?.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:["placeholder","aria-label","title"]});
}
function apply(lang){
 currentLang=lang==="en"||dictionaries[lang]?lang:"en";select.value=currentLang;
 translateNow();try{localStorage.setItem("helloearth-language",currentLang)}catch(e){}
 document.dispatchEvent(new CustomEvent("helloearth:languagechanged",{detail:{language:currentLang}}))
}
observer=new MutationObserver(records=>{if(records.some(r=>r.target&&!r.target.closest?.(".page-language-picker")))translateNow()});
window.HelloEarthI18n={get language(){return currentLang},t(key,vars){let value=dictionaries[currentLang]?.[key]??key;if(vars)for(const [k,v] of Object.entries(vars))value=value.replaceAll("{"+k+"}",String(v));return value},setLanguage:apply};
let saved;try{saved=localStorage.getItem("helloearth-language")}catch(e){}const browser=(navigator.language||"en").toLowerCase().split("-")[0];apply(saved==="en"||dictionaries[saved]?saved:dictionaries[browser]?browser:"en");
select.addEventListener("change",()=>apply(select.value));window.addEventListener("storage",e=>{if(e.key==="helloearth-language"&&e.newValue)apply(e.newValue)});
